starlark_filter.code:
def should_include(row):
    date = row["date"]
    if date == None:
        return False
    parts = date.split("-")
    shaped = len(parts) == 3 and [len(part) for part in parts] == [4, 2, 2]
    if not (shaped and "".join(parts).isdigit()):
        refuse("classify_event dated this event %r, which is not YYYY-MM-DD" % date)
    return True

