starlark.code:
def transform(row):
    if row["span"] == None:
        refuse("an event reached cite_event with no span, which quoted_only drops")
    if row["ecf_entry"] == None:
        refuse("filing %s carries no ECF number, so no pin cite can name it" % row["source_id"])
    entry = str(row["ecf_entry"])
    if row["attachment"] != None:
        entry = entry + "-" + str(row["attachment"])
    return dict(row, span=row["span"], quote=row["span"]["quote"],
                pin_cite="ECF No. " + entry + " at " + str(row["page"]),
                source_kind="court_filing")

