{spans}

starlark.code:
def transform(row):
    status = "disputed" if row["reviewed_disputed"] else "undisputed"
    contrary = [] if row["contrary"] == None else [row["contrary"]]
    return dict(row, status=status, summary=row["reviewed_summary"],
                supporting=[row["supporting"]], contrary=contrary)
